function stopSun(){sunPlaying=false;$('playSun').textContent='Play';$('playSun').setAttribute('aria-pressed','false')}
function syncSolar(){const p=Solar.parts(solarInstant,solarZone);$('solarDateInput').value=p.date;$('solarTimeInput').value=p.time;$('solarZone').value=solarZone;solarHour=Number(p.time.slice(0,2))+Number(p.time.slice(3))/60;$('sunHour').value=solarHour;$('sunHourLabel').textContent=p.time;$('solarInstant').textContent=new Intl.DateTimeFormat('en-US',{timeZone:solarZone,dateStyle:'medium',timeStyle:'short'}).format(solarInstant)+' · '+(solarZone==='UTC'?'UTC':'Pacific')+' · '+solarInstant.toISOString().slice(11,16)+' UTC';}
function applySolar(date){solarInstant=new Date(date);shadeNight=true;$('dayNight').setAttribute('aria-pressed','true');$('solarError').textContent='';syncSolar();draw()}
function editSolar(){stopSun();const matches=Solar.fromWall($('solarDateInput').value,$('solarTimeInput').value,solarZone);if(matches.length!==1){$('solarError').textContent=matches.length?'This clock time occurs twice at the daylight-saving change. Choose UTC to specify the instant.':'This local time does not exist or is invalid. Choose another time.';return}applySolar(matches[0])}
function setSolarHour(value){const h=(Number(value)+24)%24;const p=Solar.parts(solarInstant,solarZone);const time=String(Math.floor(h)).padStart(2,'0')+':'+String(Math.round(h%1*60)).padStart(2,'0');$('solarDateInput').value=p.date;$('solarTimeInput').value=time;editSolar()}
$('sunHour').oninput=e=>setSolarHour(e.target.value);$('solarDateInput').onchange=editSolar;$('solarTimeInput').onchange=editSolar;$('solarZone').onchange=e=>{solarZone=e.target.value;syncSolar();$('solarError').textContent=''};
$('sunNow').onclick=()=>{stopSun();applySolar(new Date())};$('sunForecast').onclick=()=>{stopSun();const d=forecastSolarDate();d.setUTCHours(12,0,0,0);applySolar(d)};
$('mapStyle').onchange=e=>{mapStyle=e.target.value;render()};
$('playSun').onclick=()=>{sunPlaying=!sunPlaying;$('playSun').setAttribute('aria-pressed',String(sunPlaying));$('playSun').textContent=sunPlaying?'Pause':'Play';sunLast=0;if(sunPlaying)requestAnimationFrame(animateSun)};
function animateSun(t){if(!sunPlaying)return;if(!sunLast||t-sunLast>=240){if(sunLast)applySolar(solarInstant.getTime()+900000);sunLast=t}requestAnimationFrame(animateSun)}
